<?php
declare(strict_types=1);if(empty($wams['authorized'])){http_response_code(403);exit;}$c=$wams['config'];function x(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}$rows=[];$head=[];$err='';try{$url=(string)($c['remoteUrl']??'');$ctx=stream_context_create(['http'=>['timeout'=>max(2,min(60,(int)($c['timeoutSeconds']??20))),'header'=>"Accept: text/csv,text/plain\r\nUser-Agent: WAMS-CSV/1.0\r\n"]]);$raw=@file_get_contents($url,false,$ctx);if($raw===false)throw new RuntimeException('Remote-Daten sind nicht erreichbar. Eventuell wird DNS blockiert. Versuche, sofern zulässig, die IP-Adresse.');$f=fopen('php://temp','r+');fwrite($f,$raw);rewind($f);while(($r=fgetcsv($f,0,(string)($c['delimiter']??',')))!==false)$rows[]=$r;fclose($f);if(($c['hasHeader']??true)&&$rows)$head=array_shift($rows);if(!$head&&$rows)foreach($rows[0] as $i=>$v)$head[]='Spalte '.($i+1);}catch(Throwable $e){$err=$e->getMessage();}$ref=max(0,(int)($c['refreshSeconds']??0));?><!doctype html><html lang="de"><head><meta charset="utf-8"><title><?=x($c['title']??'CSV Reporting')?></title><?php if($ref):?><meta http-equiv="refresh" content="<?=$ref?>"><?php endif?><link rel="stylesheet" href="<?=x($wams['styleUrl'])?>"></head><body><main class="csv"><div class="shell"><h1><?=x($c['heading']??'CSV Reporting')?></h1><p>Daten werden live abgerufen und nicht gespeichert.</p><?php if($err):?><div class="err"><?=x($err)?></div><?php else:?><div class="box"><input id="filter" placeholder="Filtern"><div class="scroll"><table class="table"><thead><tr><?php foreach($head as $h):?><th><?=x($h)?></th><?php endforeach?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($head as $i=>$h):?><td><?=x($r[$i]??'')?></td><?php endforeach?></tr><?php endforeach?></tbody></table></div></div><?php endif?></div></main><script src="<?=x($wams['scriptUrl'])?>"></script></body></html>
